SELECT ?app ?label ?version ?queries ?params ?type WHERE {
          ?app a <urn:acquirium#App> .
          OPTIONAL { ?app <http://www.w3.org/2000/01/rdf-schema#label> ?label }
          OPTIONAL { ?app <urn:acquirium#hasVersion> ?version }
          OPTIONAL { ?app <urn:acquirium#querySpec> ?queries }
          OPTIONAL { ?app <urn:acquirium#paramSpec> ?params }
          OPTIONAL { ?app a ?type . FILTER(?type != <urn:acquirium#App>) }
        }

SELECT ?app ?point ?ref ?qk ?unit ?ds ?backend ?rtype WHERE {
          ?app a <urn:acquirium#App> ; <urn:acquirium#produces> ?point .
          ?point <https://brickschema.org/schema/Brick/ref#hasExternalReference> ?ref .
          ?ref a ?rtype . FILTER(?rtype IN (<urn:acquirium#EventStream>, <urn:acquirium#TimeseriesStream>))
          OPTIONAL { ?point <http://qudt.org/schema/qudt/hasQuantityKind> ?qk }
          OPTIONAL { ?point <http://qudt.org/schema/qudt/hasUnit> ?unit }
          OPTIONAL { ?point <urn:acquirium#dataSource> ?ds }
          OPTIONAL { ?ref <urn:acquirium#storageBackend> ?backend }
        }

